using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpResource(Uri = "config://app/settings", Name = "App Settings",
    Description = "Returns the current application configuration")]
public class ConfigResource
{
    [ResourceMethod]
    public static string GetSettings()
    {
        var config = new
        {
            Environment = "production",
            Version = "1.2.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };
        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpToolType]
public static class WeatherTools
{
    [McpTool(Name = "get_weather"), Description("Gets the current weather for a city")]
    public static string GetWeather(
        [Description("The city name")] string city)
    {
        // Simulated weather data
        return $"Weather in {city}: 72°F, partly cloudy, humidity 45%";
    }
}

